from pysat.solvers import Glucose3, Minisat22, Cadical153
from pysat.card import CardEnc, EncType
import itertools, collections, time, sys
n=18
edge_list=[(i,j) for i in range(n) for j in range(i+1,n)]
eid={e:k+1 for k,e in enumerate(edge_list)}
# exactly 27
vpool_top=len(edge_list)
enc=CardEnc.equals(lits=list(eid.values()), bound=27, encoding=EncType.seqcounter, top_id=vpool_top)
print('vars',enc.nv,'clauses',len(enc.clauses))
solver=Cadical153(bootstrap_with=enc.clauses)

def get_edges(model):
    pos=set(l for l in model if l>0 and l<=len(edge_list))
    return [edge_list[l-1] for l in pos]

def find_small_cycles(edges):
    adj=[set() for _ in range(n)]
    for u,v in edges: adj[u].add(v); adj[v].add(u)
    cycles=[]
    # enumerate simple cycles length 3-6 canonical in this graph
    def dfs(start, path):
        cur=path[-1]
        if len(path)>6: return
        for nb in adj[cur]:
            if nb==start and len(path)>=3:
                cyc=path[:]
                if len(cyc)<=6:
                    # canonical: start is min, path[1]<path[-1]
                    if start==min(cyc) and cyc[1]<cyc[-1]:
                        cycles.append(tuple(cyc))
            elif nb not in path and nb>=start: # ensure start min
                if len(path)<6:
                    dfs(start, path+[nb])
    for s in range(n): dfs(s,[s])
    return cycles

start=time.time(); it=0; total_added=0
while True:
    it+=1
