    if not sat:
        print('UNSAT after',it,'added',total_added,'time',time.time()-start)
        break
    edges=get_edges(solver.get_model())
    cycles=find_small_cycles(edges)
    if not cycles:
        print('FOUND',len(edges),'it',it,'time',time.time()-start)
